// Optimized traversal:
// - First, scale C by beta:   C[i,j] *= beta
//   traversed i-major, j-minor => contiguous accesses in C
// - Then, compute alpha*A*B:
//     for i
//       for k
//         a_ik = A[i,k]                 (reused across all j)
//         for j
//           C[i,j] += alpha*a_ik*B[k,j]
//
//   Here j is the innermost dimension, which is contiguous in both C and B
//   (C: i x j, B: k x j). This improves spatial locality and allows the
//   compiler to vectorize the inner loop efficiently.
//
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop

	// ---------------------------------------------------------------------
	// 1) Scale C by beta: C[i,j] *= beta
	//    We traverse C only (no reason to bring A/B into cache here).
	// ---------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has dimension 'i' fixed, only 'j' remains
		trav_i.for_each([&](auto state) {
			C[state] *= beta;
		});
	});

	// ---------------------------------------------------------------------
	// 2) GEMM accumulation: C[i,j] += alpha * sum_k A[i,k] * B[k,j]
	//
	// Traversal order: i (outer) -> k (middle) -> j (inner)
	// - A is laid out as (i x k) with k inner  -> good locality for A along k
	// - B is laid out as (k x j) with j inner  -> good locality for B along j
	// - C is laid out as (i x j) with j inner  -> good locality for C along j
	//
	// For each fixed (i,k), we load A[i,k] once and reuse it across the full
	// inner j loop where accesses to B[k,j] and C[i,j] are contiguous.
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// 'i' is fixed here; remaining dimensions are 'j' and 'k'
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed; only 'j' remains to iterate

			// Get the (i,k) state once and cache A[i,k] in a register
			auto state_ik = trav_ik.state();
			num_t a_ik = A[state_ik];

			// Now iterate over all j (the only remaining dimension)
			trav_ik.for_each([&](auto state) {
				// state contains (i, j, k); C ignores 'k', B ignores 'i'
				C[state] += alpha * a_ik * B[state];
			});
		});
	});

#pragma endscop
